    // ImageParam to represent the "previous" time-step array in Halide
    ImageParam A_prev_param(type_of<num_t>(), 2, "A_prev");

    // Vars for spatial indices
    Var x("x"), y("y");

    // One time-step of the 2D Seidel/Jacobi-like update, expressed in Halide.
    //
    // Original C update (for interior points 1..n-2):
    //
    // A[i][j] = (A[i-1][j-1] + A[i-1][j] + A[i-1][j+1]
    //            + A[i][j-1] + A[i][j] + A[i][j+1]
    //            + A[i+1][j-1] + A[i+1][j] + A[i+1][j+1]) / 9.0;
    //
    // Boundaries (i == 0 or i == n-1 or j == 0 or j == n-1) remain unchanged.
    //
    // Mapping to Halide coordinates: i -> y, j -> x, A[i][j] -> A_prev_param(x, y).
    Func prev_clamped("prev_clamped");
    Func seidel_step("seidel_step");

    // Precompute 1/9 as a scalar and lift it into a Halide Expr.
    const num_t inv_denom_scalar = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);
    Expr inv_denom = inv_denom_scalar;

    // Clamp reads to stay within [0, n-1] in both dimensions. This guarantees
    // that even if the interior expression is evaluated at boundary points
    // due to scheduling or select lowering, we never read out-of-bounds.
    Expr x_min = 0;
    Expr y_min = 0;
    Expr x_max = n - 1;
    Expr y_max = n - 1;

    prev_clamped(x, y) = A_prev_param(clamp(x, x_min, x_max),
                                      clamp(y, y_min, y_max));

    // Predicate that selects interior points (those updated by the stencil).
    Expr is_interior =
        (x > 0) && (x < n - 1) &&
        (y > 0) && (y < n - 1);

    // 3x3 stencil average over the previous time step, using the clamped
    // wrapper to keep all accesses in-bounds. For true interior points the
    // clamp is a no-op; for boundaries we still compute this expression but
    // then ignore it via 'select' below.
    Expr stencil_sum =
        prev_clamped(x - 1, y - 1) +
        prev_clamped(x - 1, y)     +
        prev_clamped(x - 1, y + 1) +
        prev_clamped(x,     y - 1) +
        prev_clamped(x,     y)     +
        prev_clamped(x,     y + 1) +
        prev_clamped(x + 1, y - 1) +
        prev_clamped(x + 1, y)     +
        prev_clamped(x + 1, y + 1);

    Expr interior_val = stencil_sum * inv_denom;

    // For interior points use the stencil; for boundaries copy the previous
    // value unchanged. This exactly matches the original C semantics.
    seidel_step(x, y) = select(is_interior,
                               interior_val,
                               A_prev_param(x, y));

    // --- Schedule for the per-step stencil ------------------------------
    //
    // We compute seidel_step at root and apply:
    //   * 2D tiling for better cache locality,
    //   * parallelization across tiles in y,
    //   * vectorization across x (fastest varying dimension).
    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    const int tile_x = 64;   // tile width in x (columns)
    const int tile_y = 32;   // tile height in y (rows)
    const int vec_width = 8; // SIMD width along x (good default on modern x64)

    seidel_step
        .compute_root()
        // Work on tile_y x tile_x blocks; Halide handles edge tiles automatically.
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
        // Vectorize contiguous x within each tile for efficient SIMD.
        .vectorize(xi, vec_width)
        // Parallelize across tiles in the y direction; each tile row is independent
        // for a fixed time step because all reads come from A_prev_param.
        .parallel(yo);

    // JIT-compile the per-time-step pipeline once
    seidel_step.compile_jit();

